//! The launcher's own changes to the files Isoloom generates: its conventions, applied by the
//! launcher right after Isoloom's defaults (`defaults::apply_to_files`), never asked of Isoloom.
//!
//! - The Compose project: a lab on this machine's Docker runs as `cyberctf-<lab id>` (see
//!   `docker::project`), not under its spec's name, so two labs declaring the same name never
//!   share containers. Every Compose call passes it (`-p`); the generated file names it too, so
//!   the file run by hand (`docker compose -f .isoloom/docker/compose.yml ps`) finds the lab.
//! - Host ports (`CYBERCTF_PORTS`, random or the lab's own) can't be decided here: they are
//!   picked from the free ports at a lab's first start and kept across starts, so they stay a
//!   Compose override file of their own (`docker::lifecycle`), added to every Compose call.

use isoloom_core::GeneratedFile;

/// What the launcher changes in a target's generated files.
#[derive(Debug, Default, PartialEq)]
pub struct Overrides {
    /// The Compose project the lab's containers run as, on local Docker.
    pub compose_project: Option<String>,
}

/// `files` with the launcher's overrides applied (paths as Isoloom wrote them, before an
/// instance moves them).
pub fn apply(files: Vec<GeneratedFile>, o: &Overrides) -> Vec<GeneratedFile> {
    files
        .into_iter()
        .map(|mut f| {
            if let Some(project) = &o.compose_project
                && f.path == format!("{}/docker/compose.yml", isoloom_core::OUTPUT_DIR)
            {
                f.contents = with_project(&f.contents, project);
            }
            f
        })
        .collect()
}

/// A Compose file with its top-level `name:` set to `project` (a plain name: lowercase letters,
/// digits, `-` and `_`, as Compose requires).
fn with_project(compose: &str, project: &str) -> String {
    let mut done = false;
    let mut out: String = compose
        .lines()
        .map(|l| {
            if !done && l.starts_with("name:") {
                done = true;
                format!("name: {project}\n")
            } else {
                format!("{l}\n")
            }
        })
        .collect();
    if !compose.ends_with('\n') {
        out.pop();
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn file(path: &str, contents: &str) -> GeneratedFile {
        GeneratedFile { path: path.into(), contents: contents.into() }
    }

    #[test]
    fn the_compose_file_names_the_launchers_project() {
        let compose = "# Generated by Isoloom\n\nname: shop\nservices:\n  web:\n    environment:\n      name: shop\n";
        let o = Overrides { compose_project: Some("cyberctf-shop-2".into()) };
        let out = apply(vec![file(".isoloom/docker/compose.yml", compose), file(".isoloom/docker-vm/Vagrantfile", "name: shop\n")], &o);
        assert_eq!(out[0].contents, "# Generated by Isoloom\n\nname: cyberctf-shop-2\nservices:\n  web:\n    environment:\n      name: shop\n");
        // Only that file: the one inside a VM keeps the spec's name.
        assert_eq!(out[1].contents, "name: shop\n");
        // No overrides, nothing changes.
        let same = apply(vec![file(".isoloom/docker/compose.yml", compose)], &Overrides::default());
        assert_eq!(same[0].contents, compose);
        assert_eq!(with_project("name: a", "b"), "name: b");
    }
}
